def validate_and_extract_values(input_dict):
    # Check all keys are strings
    for key in input_dict:
        if not isinstance(key, str):
            raise ValueError("All keys in the dictionary must be strings")
    # Check all values are strings
    for value in input_dict.values():
        if not isinstance(value, str):
            raise ValueError("All values in the dictionary must be strings")
    # Return a tuple of all values
    return tuple(input_dict.values())

