**STEP 2: Configure Express App**  
Set up the Express server and middleware (e.g., for parsing JSON bodies).  
```javascript  
const express = require('express');  
const app = express();  
app.use(express.json());  
app.use(bodyParser.urlencoded({ extended: true }));  
```  

**STEP 3: Create the User Authentication Route**  
Implement a POST endpoint to issue a JWT token. Replace `[USER verifying logic]` with your authentication check.  
```javascript  
const jwt = require('jsonwebtoken');  

app.post('/api/auth/token', (req, res) => {  
  // [USER verifying logic: e.g., check username/password]  
  const { username, password } = req.body;  
  // ... authentication check ...  
  if (isValidUser(username, password)) {  
    const data = { userId: user.id }; // Replace with actual user ID  
    const token = jwt.sign(data, [SECRET_KEY], {  
      expiresIn: [TOKEN_EXPIRATION] // e.g., "3600s" for 1 hour  
    });  
    res.json({ token });  
  } else {  
    res.status(401).json({ error: "Unauthorized" });  
  }  
});  
```  

**STEP 4: Add Token Verification Middleware**  
Attach middleware to protect routes. Use the chosen JWT library to verify tokens.  
```javascript  
function verifyToken(req, res, next) {  
  const authHeader = req.headers['authorization'];  
  if (!authHeader) return res.status(403).send('No token provided');  
  const token = authHeader.split(' ')[1]; // For "Bearer <token>" format  
  jwt.verify(token, [SECRET_KEY], (err, userData) => {  
    if (err) return res.status(400).send('Invalid token');  
    req.user = userData; // Attach user data to request  
    next();  
  });  
}  

// Apply to protected routes  
app.get('/api/user', verifyToken, (req, res) => {  
  res.json({ userId: req.user.id });  
});  
```  

