npm install express-jwt  
```  

**STEP 2: Configure express-jwt Settings**  
Create a config file (e.g., `jwt.config.js`) with placeholders for customization.  
```javascript  
module.exports = {  
  secret: [JWT_SECRET_KEY],  
  signingAlgorithm: 'RS256', // Or 'HS256'  
  tokenExpireInMinutes: [TOKEN_EXPIRATION], // e.g., 60 for 1 hour  
  // Other options like tokenValidUntil, etc.  
};  
```  

**STEP 3: Set Up express-jwt in the App**  
Integrate the config into your Express app.  
```javascript  
const jwt = require('express-jwt');  
const jwtConfig = require('./jwt.config');  

app.use(  
  jwt(  
    jwtConfig,  
    function (req, res, next) {  
      // Attach user data if needed  
      next();  
    }  
  )  
);  
```  

