function reverseVowelsWithStats([inputStr]) {
    const vowels = ['a', 'e', 'i', 'o', 'u'];
    let vowelIndices = [];
    let originalChars = [...inputStr]; // [step1] Create a copy of the original characters

    // [step2] Collect indices of all vowels (case-insensitive check)
    for (let i = 0; i < inputStr.length; i++) {
        const lowerChar = inputStr[i].toLowerCase();
        if (vowels.includes(lowerChar)) {
            vowelIndices.push(i);
        }
    }

    // [step3] Extract the vowels in order and reverse their sequence
    let vowelValues = vowelIndices.map(idx => originalChars[idx]).reverse();

    // [step4] Replace vowels in original order with reversed vowels
    for (let i = 0; i < vowelValues.length; i++) {
        const pos = vowelIndices[i];
        originalChars[pos] = vowelValues[i];
