    const reversedString = originalChars.join('');
    // [step5] Count vowels case-insensitively
    const count = {};
    for (const c of inputStr.toLowerCase()) {
        if (vowels.includes(c)) {
            count[c] = (count[c] || 0) + 1;
        }
    }

