"double findMedian(vector<double>& nums, int size) {
    sort(nums.begin(), nums.end());
    if (size % 2 == 1) // odd
        return nums[size / 2];
    else // even
        return (nums[(size - 1) / 2] + nums[size / 2]) / 2.0;
}

