def second_smallest_3d(arr):
    first = second = None
    for d in arr:
        for mat in d:
            for num in mat:
                if first is None or num < first:
                    if first is not None and (first > num or (first is None and num != first)):
                        second = first
                        first = num
                    elif first is None or (num != first and (second is None or num < second)):
                        if num != first:
                            if second is None or num < second:
                                second = num
    # Handle cases where there aren't at least two distinct elements
    found = False
    if first is not None and (second is not None and second != first):
        found = True
    if not found:
        return None
    return second

